g=[[1]*22 for _ in range(12)]
pts={1:[1,2,3,5,7,8,9,12],2:[1],3:[1],4:[1,12],7:[1],8:[12],9:[1],10:[1,12],11:[1,2,5,6,7,8,9,11,12]}
for r,cs in pts.items():
 for c in cs:g[r][c]=0
# fill all 1s between pairs of 0s in each row and column
out=[row[:] for row in g]
for r in range(12):
 cs=[c for c,v in enumerate(g[r]) if v==0]
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b):out[r][c]=2
for c in range(22):
 rs=[r for r in range(12) if g[r][c]==0]
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b):out[r][c]=2
print(out)
